h=load_history()
def parse(x):
 out=[]
 for s in re.split(r'### Choice ([A-E])',x['question'])[1:]:
  pass
 chunks=re.split(r'### Choice ([A-E])',x['question'])
 for i in range(1,len(chunks),2):
  a,s=chunks[i:i+2]
  def get(p):
   z=re.search(p,s); return z.group(1) if z else None
  try:
   out.append(dict(letter=a,depth=int(get(r'- Depth: (\d+)')),width=int(get(r'- Width: (\d+)')),res=get(r'- Residual connections: (True|False)')=='True',ln=ast.literal_eval(get(r'- Layer norm per layer: (\[[^\n]+\])')),act=get(r'- Activation: (\w+)'),opt=get(r'- Optimizer: (\w+)'),lr=float(get(r'- Learning rate: ([\deE.+-]+)')),mom=get(r'- Momentum: ([\d.]+)'),wd=get(r'- Weight decay: ([\deE.+-]+)')))
  except: pass
 return out
pairs=[]
for x in h:
 if x['family']!='univariate_regression':continue
 cs=parse(x)
 if '<' not in x['answer']:continue
 for a,b in itertools.combinations(cs,2):
  if a['opt']==b['opt']=='SGD' and a['lr']==b['lr'] and a['mom']==b['mom'] and a['res']==b['res']==True:
   if a['act'] in ['gelu','silu'] and b['act'] in ['relu','leaky_relu']:sm,rc=a,b
   elif b['act'] in ['gelu','silu'] and a['act'] in ['relu','leaky_relu']:sm,rc=b,a
   else:continue
   if sm['ln'][-1] and not rc['ln'][-1]:
    pairs.append((x['question_id'],sm['depth'],rc['depth'],sum(sm['ln']),sum(rc['ln']),sm['lr'],sm['mom'],x['answer'].index(sm['letter'])<x['answer'].index(rc['letter'])))
print('smooth terminal vs rectifier nonterminal',len(pairs),sum(x[-1] for x in pairs));print(pairs)
"}

